<input type="hidden" name="package_id" value="0">
<?php if(!empty($c['credit_bundles'])): ?><div class="row"><?php foreach($c['credit_bundles'] as $bundle): ?><button class="btn secondary" type="button" data-amount="<?= $h($bundle['amount_kobo']/100); ?>" data-bundle="<?= (int)$bundle['id']; ?>" data-units="<?= (int)$bundle['credit_units']; ?>"><?= $h($bundle['name']); ?> · <?= $money($bundle['amount_kobo']); ?> / <?= number_format($bundle['credit_units']); ?> credits</button><?php endforeach; ?></div><?php endif; ?>
<div class="row" style="margin-top:12px"><?php foreach($c['packages'] as $amount):if($amount*100<($c['minimum_kobo']??10000))continue; ?><button class="btn secondary" type="button" data-amount="<?= $h($amount); ?>">₦<?= number_format($amount); ?></button><?php endforeach; ?></div>
<label>Amount (NGN) · or enter a custom amount<input name="amount" type="number" min="<?= $h(($c['minimum_kobo']??10000)/100); ?>" data-min="<?= $h(($c['minimum_kobo']??10000)/100); ?>" max="500000" step="0.01" required data-rate="<?= (int)$c['credit_price_kobo']; ?>"></label><p class="muted" data-credit-quote>Choose an amount or bundle to see your credits.</p>
